function cat = plural(n)
  if (n == 0)
    cat = "zero";
  elseif (n == 1)
    cat = "one";
  elseif (n == 2)
    cat = "two";
  else
    mod100 = mod(n, 100);
    if (mod100 >= 3 && mod100 <= 10)
      cat = "few";
    elseif (mod100 >= 11 && mod100 <= 99)
      cat = "many";
    else
      cat = "other";
    endif
  endif
endfunction
